import{_ as n,o as t,c as o,a4 as s}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse(`{"title":"ADR-0013 — Métadonnées SEO dans le panneau de configuration d'un enregistrement","description":"Extrait de docs/adr/0013-metadonnees-seo-dans-le-panneau-de-configuration.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0013 — Métadonnées SEO dans le panneau de configuration d'un enregistrement","description":"Extrait de docs/adr/0013-metadonnees-seo-dans-le-panneau-de-configuration.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0013-metadonnees-seo-dans-le-panneau-de-configuration.md","filePath":"developpeurs/adr/0013-metadonnees-seo-dans-le-panneau-de-configuration.md"}`),a={name:"developpeurs/adr/0013-metadonnees-seo-dans-le-panneau-de-configuration.md"};function i(r,e,d,c,u,l){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0013--métadonnées-seo-dans-le-panneau-de-configuration-dun-enregistrement" tabindex="-1">ADR-0013 — Métadonnées SEO dans le panneau de configuration d&#39;un enregistrement <a class="header-anchor" href="#adr-0013--métadonnées-seo-dans-le-panneau-de-configuration-dun-enregistrement" aria-label="Permalink to &quot;ADR-0013 — Métadonnées SEO dans le panneau de configuration d&#39;un enregistrement {#adr-0013--métadonnées-seo-dans-le-panneau-de-configuration-dun-enregistrement}&quot;">​</a></h1><p><strong>Date :</strong> 20 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §6.1 (panneau de configuration), §14.9 (fonctions éditoriales, SEO assisté) ; plan d&#39;action agile §5 (V1.1, « E9 (suite : obsolescence, SEO assisté) »)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le SEO assisté est une fonction éditoriale de l&#39;Epic E9 : un modèle propose un titre et une description méta, un agent les accepte, et <strong>quelque chose</strong> doit alors être écrit quelque part. Or, au moment d&#39;ouvrir cette tranche, <strong>aucun champ SEO n&#39;existait nulle part dans le schéma</strong> — ni colonne, ni entrée du panneau de configuration, ni convention de nommage dans les Content Types livrés.</p><p>Le CDC ne détaille pas le schéma attendu : il nomme la fonction (§14.9) et décrit le panneau de configuration d&#39;un enregistrement (§6.1) sans y faire figurer le référencement. La question à trancher n&#39;est donc pas « comment produire une balise » mais « de quelle nature est une balise méta dans ce CMS » — et cette réponse détermine qui peut en avoir une, qui peut la modifier, et ce qu&#39;il en advient lors d&#39;une reprise de données.</p><p>Trois rangements étaient possibles, et ils ne se valent pas :</p><ul><li>dans <code>content_entries.data</code>, c&#39;est-à-dire comme un <strong>champ déclaré par un Content Type</strong> (Field Engine, E1) ;</li><li>dans <code>content_entries.settings</code>, c&#39;est-à-dire dans le <strong>panneau de configuration</strong> (E4) ;</li><li>dans une table dédiée.</li></ul><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Les métadonnées de référencement vivent dans le panneau de configuration</strong>, sous la forme d&#39;un sous-objet <code>settings.seo</code> typé par <code>SeoMetadata</code> (<code>app/lifecycle/settings.py</code>) : <code>meta_title</code>, <code>meta_description</code>, plus la provenance (<code>source</code>, <code>suggestion_id</code>, <code>updated_at</code>).</p><p>Le critère qui tranche est celui que la docstring d&#39;<code>app/lifecycle/settings.py</code> pose depuis E4 : le panneau contient ce qui relève de la <strong>publication</strong> d&#39;un enregistrement, pas de son <strong>contenu</strong>. Un titre et une description méta ne disent pas ce que la page raconte — ils disent comment elle est <em>exposée</em> à un moteur de recherche et à un partage social. C&#39;est exactement la catégorie de <code>slug</code> (l&#39;URL), de <code>overline</code> (le surtitre) et de <code>image_id</code>, tous rangés là pour ce motif.</p><p>Deux conséquences en découlent, et ce sont elles qui motivent la décision :</p><ol><li><strong>Tout enregistrement peut avoir des métadonnées SEO, y compris un Content Type inventé cinq minutes plus tôt.</strong> C&#39;est le même raisonnement que pour le critère de succès n°20 en E4 : faire dépendre le référencement d&#39;un site de la bonne volonté de celui qui a créé le Content Type produirait des types « qu&#39;on ne peut pas référencer », et personne ne l&#39;apprendrait avant la mise en ligne.</li><li><strong>Le SEO assisté a une cible commune où déposer sa proposition.</strong> Une suggestion vise un <code>field_path</code> (<code>app/ai/suggestions.py</code>) ; sans champ canonique, chaque Content Type aurait eu le sien, et « appliquer une proposition acceptée » serait devenu une correspondance à configurer par type.</li></ol><p><strong>Un sous-objet, pas deux champs plats.</strong> <code>settings.seo</code> suit la forme d&#39;<code>obsolescence</code> et d&#39;<code>usefulness_survey</code> : une préoccupation cohérente et destinée à grandir (<code>noindex</code>, URL canonique, image de partage) tient mieux dans un groupe nommé, et une suggestion IA vise ainsi <strong>un</strong> chemin (<code>seo</code>) plutôt que deux — ce qui compte, puisqu&#39;une proposition SEO produit toujours le titre et la description ensemble.</p><p><strong>Aucune migration.</strong> <code>content_entries.settings</code> est une colonne JSONB depuis E4 (elle l&#39;est parce qu&#39;un plugin doit pouvoir injecter un champ dans le panneau, cf. §7.3) : ajouter un sous-objet typé est une modification de modèle Pydantic, pas de schéma SQL. Le contrôle a été refait à cette occasion sur une base neuve migrée à <code>head</code> : <code>alembic revision --autogenerate</code> ne produit <strong>aucune</strong> opération <code>add_column</code>, <code>drop_column</code>, <code>create_table</code> ni <code>drop_table</code>. (Il subsiste un écart de réflexion antérieur à cette décision, sans rapport avec elle : Alembic ne sait pas relire les index d&#39;expression posés par les migrations 0004/0005 ni les <code>server_default</code> de <code>created_at</code>/<code>updated_at</code>, et les propose donc à la recréation à chaque exécution.)</p><p><strong>Les longueurs recommandées ne sont pas des contraintes de schéma.</strong> ~60 caractères pour un titre, ~160 pour une description sont des usages de moteurs, qui changent. <code>SeoMetadata</code> borne le <strong>stockage</strong> (255 / 500) ; le dépassement de l&#39;usage revient à l&#39;agent sous forme d&#39;avertissement (<code>app/ai_editorial/seo.py:seo_warnings</code>). Tronquer automatiquement couperait au milieu d&#39;un mot la phrase que les usagers d&#39;une collectivité lisent dans leur moteur de recherche.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Champs déclarés par chaque Content Type (<code>data</code>)</strong></td><td>Écartée : le référencement d&#39;un site dépendrait de ce que chaque créateur de type a pensé à déclarer, et deux types nommeraient les mêmes balises différemment (<code>meta_desc</code>, <code>description_seo</code>, <code>seo_description</code>). Le générateur de sitemap et le rendu du <code>&lt;head&gt;</code> devraient alors connaître chaque type — exactement ce que le panneau de configuration existe pour éviter.</td></tr><tr><td><strong>Colonnes SQL dédiées sur <code>content_entries</code></strong></td><td>Écartée : une migration pour deux champs dont on sait qu&#39;ils vont grandir (<code>noindex</code>, canonique, image de partage), alors que la colonne <code>settings</code> existe précisément pour accueillir ce genre d&#39;ajout sans migration. Le typage revient de toute façon par Pydantic, comme pour le reste du panneau.</td></tr><tr><td><strong>Table <code>seo_metadata</code> dédiée</strong></td><td>Écartée : une jointure de plus sur le chemin de rendu le plus fréquent du site public, pour une donnée qui accompagne toujours son enregistrement, ne survit pas sans lui, et se purge avec lui.</td></tr><tr><td><strong>Déduire les balises du contenu au moment du rendu, sans les stocker</strong></td><td>Écartée : c&#39;est le comportement de <em>repli</em> souhaitable (une page sans <code>meta_description</code> peut retomber sur son chapeau), pas un rangement. Il ne laisse aucune place à une correction manuelle, ni à une proposition acceptée, et rend le SEO assisté sans objet.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Tout enregistrement est référençable, sans déclaration préalable et sans code par Content Type.</li><li>Le SEO assisté dispose d&#39;une cible unique (<code>settings.seo</code>), donc d&#39;un chemin d&#39;application unique depuis une suggestion acceptée.</li><li>Aucune migration, et le point d&#39;extension du panneau (E4/E7) reste le seul mécanisme d&#39;ajout de réglage.</li><li>La provenance est portée par la donnée (<code>source</code>, <code>suggestion_id</code>), ce que <code>app/ai/suggestions.py</code> demandait explicitement à la fonction éditoriale : savoir, un an plus tard, d&#39;où vient le texte publié.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Les métadonnées SEO ne sont pas traduisibles par le mécanisme des champs de contenu.</strong> <code>settings</code> n&#39;est pas multilingue ; une suggestion, elle, porte une <code>locale</code>. Tant que le CMS reste monolingue par site, l&#39;écart est théorique — mais l&#39;Epic multilingue devra trancher (probablement <code>settings.seo</code> par locale), et il faut le savoir avant plutôt qu&#39;après.</li><li>Un plugin ne peut pas remplacer le rangement des balises : il peut ajouter un réglage à côté (<code>settings.extra</code>), pas redéfinir <code>seo</code>. C&#39;est voulu (un plugin ne doit pas pouvoir défaire le référencement d&#39;un site), mais cela ferme une extension.</li><li>La validation de cohérence <code>source</code> / <code>suggestion_id</code> vit dans le modèle Pydantic, donc dans le panneau : une écriture directe en base la contournerait. La trace faisant foi reste la ligne d&#39;<code>ai_suggestions</code>, avec son relecteur et sa date ; ces deux champs sont un renvoi, pas une preuve.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Epic multilingue : trancher la déclinaison de <code>settings.seo</code> par locale, en même temps que le reste du panneau de configuration. → <strong>Tranché par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0025-multilinguisme-groupe-de-traduction">ADR-0025</a> : sans déclinaison.</strong> Chaque version linguistique d&#39;un contenu est un enregistrement autonome, donc porteuse de son propre panneau de configuration — et donc de ses propres <code>settings.seo</code>, <code>slug</code> et <code>overline</code>. La négative relevée ci-dessus n&#39;a plus d&#39;objet.</li><li>[x] Epic E15 (Conformité générée) / rendu public : consommer <code>settings.seo</code> pour le <code>&lt;head&gt;</code> et le sitemap, avec repli sur le titre du contenu quand <code>meta_title</code> est nul. → <strong><code>&lt;head&gt;</code> fait par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0034-adresses-publiques">ADR-0034</a></strong> : la route de résolution sert un <code>seo</code> déjà résolu (titre et description avec repli, canonique, versions linguistiques). Le sitemap est livré par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0035-plan-de-site-flux-et-robots">ADR-0035</a>.</li></ul>',24)])])}const m=n(a,[["render",i]]);export{g as __pageData,m as default};
